1	import type { ListItem } from "mdast";
2	import { fromMarkdown } from "mdast-util-from-markdown";
3	import { gfmFromMarkdown } from "mdast-util-gfm";
4	import { gfm } from "micromark-extension-gfm";
5	import { visit } from "unist-util-visit";
6	
7	interface SourceRange {
8	  start: number;
9	  end: number;
10	}
11	
12	interface MarkdownEdit extends SourceRange {
13	  replacement: string;
14	}
15	
16	interface ParsedTaskItem {
17	  checked: boolean;
18	  checkboxMarker: SourceRange;
19	}
20	
21	interface LineInfo {
22	  text: string;
23	  startOffset: number;
24	  endOffset: number;
25	}
26	
27	const TASK_LINE_REGEXP = /^(\s*)((?:[-*+])|(?:\d+[.)]))(\s+)\[([ xX])\]/;
28	
29	function getLineStarts(markdown: string): number[] {
30	  const starts = [0];
31	  for (let index = 0; index < markdown.length; index++) {
32	    if (markdown[index] === "\n") {
33	      starts.push(index + 1);
34	    }
35	  }
36	  return starts;
37	}
38	
39	function getLineInfo(markdown: string, lineStarts: number[], lineNumber: number): LineInfo | undefined {
40	  const startOffset = lineStarts[lineNumber];
41	  if (startOffset === undefined) {
42	    return undefined;
43	  }
44	
45	  const nextLineStart = lineStarts[lineNumber + 1];
46	  const endOffset = nextLineStart === undefined ? markdown.length : nextLineStart - 1;
47	  return {
48	    text: markdown.slice(startOffset, endOffset),
49	    startOffset,
50	    endOffset,
51	  };
52	}
53	
54	function parseMarkdown(markdown: string) {
55	  return fromMarkdown(markdown, {
56	    extensions: [gfm()],
57	    mdastExtensions: [gfmFromMarkdown()],
58	  });
59	}
60	
61	function parseTaskItems(markdown: string): ParsedTaskItem[] {
62	  let tree: ReturnType<typeof parseMarkdown>;
63	  try {
64	    tree = parseMarkdown(markdown);
65	  } catch {
66	    return [];
67	  }
68	
69	  const lineStarts = getLineStarts(markdown);
70	  const tasks: ParsedTaskItem[] = [];
71	
72	  visit(tree, "listItem", (node: ListItem) => {
73	    if (typeof node.checked !== "boolean") {
74	      return;
75	    }
76	
77	    const startLine = node.position ? node.position.start.line - 1 : undefined;
78	    if (startLine === undefined) {
79	      return;
80	    }
81	
82	    const lineInfo = getLineInfo(markdown, lineStarts, startLine);
83	    if (!lineInfo) {
84	      return;
85	    }
86	
87	    const match = lineInfo.text.match(TASK_LINE_REGEXP);
88	    if (!match || match.index !== 0) {
89	      return;
90	    }
91	
92	    const markerStart = lineInfo.startOffset + match[1].length + match[2].length + match[3].length + 1;
93	
94	    tasks.push({
95	      checked: node.checked,
96	      checkboxMarker: {
97	        start: markerStart,
98	        end: markerStart + 1,
99	      },
100	    });
101	  });
102	
103	  return tasks;
104	}
105	
106	function applyMarkdownEdits(markdown: string, edits: MarkdownEdit[]): string {
107	  if (edits.length === 0) {
108	    return markdown;
109	  }
110	
111	  const sortedEdits = [...edits].sort((a, b) => a.start - b.start);
112	  let previousEnd = 0;
113	  for (const edit of sortedEdits) {
114	    if (edit.start < 0 || edit.end < edit.start || edit.end > markdown.length || edit.start < previousEnd) {
115	      return markdown;
116	    }
117	    previousEnd = edit.end;
118	  }
119	
120	  let nextMarkdown = markdown;
121	  for (let index = sortedEdits.length - 1; index >= 0; index--) {
122	    const edit = sortedEdits[index];
123	    nextMarkdown = `${nextMarkdown.slice(0, edit.start)}${edit.replacement}${nextMarkdown.slice(edit.end)}`;
124	  }
125	  return nextMarkdown;
126	}
127	
128	function setAllTaskMarkers(markdown: string, checked: boolean): string {
129	  const marker = checked ? "x" : " ";
130	  const edits = parseTaskItems(markdown)
131	    .filter((task) => task.checked !== checked)
132	    .map<MarkdownEdit>((task) => ({
133	      start: task.checkboxMarker.start,
134	      end: task.checkboxMarker.end,
135	      replacement: marker,
136	    }));
137	
138	  return applyMarkdownEdits(markdown, edits);
139	}
140	
141	export function uncheckAllTasks(markdown: string): string {
142	  return setAllTaskMarkers(markdown, false);
143	}
144	
145	export function checkAllTasks(markdown: string): string {
146	  return setAllTaskMarkers(markdown, true);
147	}
